fn sqlite_snapshot_semio_mesh_independent_vertex_join_and_material_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query('SELECT vertex_index,x,y,z FROM semio_mesh_index JOIN semio_mesh_position ON semio_mesh_index.primitive_id=semio_mesh_position.primitive_id AND semio_mesh_index.vertex_index=semio_mesh_position.ordinal WHERE semio_mesh_index.primitive_id=1 ORDER BY semio_mesh_index.ordinal').all();if(rows.length!==3||rows[1].x!==1||rows[2].y!==1)throw Error('vertices');db.query('UPDATE semio_mesh_material SET metallic=0.5,metallic_ieee754_bits=1056964608').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.materials[0].metallic=0.5;assert_eq!(restored,expected);}

