test("Semio Mesh code-admitted intermediate owner survives independently queried physical SQLite",async()=>{
 const neutral=await Bun.file(new URL("../🧫️fixtures/🧩️intermediate/🔣️.json",import.meta.url)).json();
 const {default:Ajv}=await import("ajv");expect(neutral["role"]).toEqual("codeAdmittedIntermediateOwner");expect(neutral["snapshot"]).toEqual({"schema":"mesh\u0000世界","meshes":[{"id":"mesh","primitives":[{"id":"primitive","topology":"points","positions":[],"normals":[],"uvs":[],"colors":[],"indices":[4294967295],"materialId":"unmatched-material\u0000世界"}]}],"materials":[{"id":"material","baseColor":{"r":0,"g":0,"b":0,"a":0},"metallic":0,"roughness":0,"baseColorTexture":"unmatched-base","metallicRoughnessTexture":"unmatched-metallic","normalTexture":"unmatched-normal","occlusionTexture":"unmatched-occlusion","emissiveTexture":"unmatched-emissive"}],"textures":[]});expect(neutral["query"]).toEqual("SELECT vertex_index FROM semio_mesh_index ORDER BY ordinal");expect(neutral["expectedRows"]).toEqual([{"vertex_index":4294967295}]);
 const input=structuredClone(neutral.snapshot);for(const material of input.materials){for(const key of ["r","g","b","a"] as const)material.baseColor[key]=binary32(material.baseColor[key]);material.metallic=binary32(material.metallic);material.roughness=binary32(material.roughness);}
 const db=Database.deserialize(await exportSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(input)));
 try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(neutral.query).all()).toEqual(neutral.expectedRows);expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_mesh_primitive SET material_native_id=?").run("independently edited");input.meshes[0].primitives[0].materialId="independently edited";expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);console.log("[DEBUG] Semio mesh independently retains unresolved material and five texture names plus empty positions and raw u32 maximum indices");}finally{db.close();}
});

